import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_scale_bn_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_scale_bn_kernel(
    const float* input,
    const float* scale,
    const float* bn_weight,
    const float* bn_bias,
    float* running_mean,
    float* running_var,
    float* output,
    int batch_size,
    int num_features,
    float eps,
    float momentum,
    bool is_training) {

    int feature_idx = blockIdx.x;
    if (feature_idx >= num_features) return;

    extern __shared__ float shared_mem[];
    float* sum_shared = shared_mem;
    float* sum_sq_shared = &shared_mem[blockDim.x];

    float s = scale[feature_idx];
    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    for (int i = threadIdx.x; i < batch_size; i += blockDim.x) {
        int idx = i * num_features + feature_idx;
        float val = input[idx] * s;
        thread_sum += val;
        thread_sum_sq += val * val;
    }

    sum_shared[threadIdx.x] = thread_sum;
    sum_sq_shared[threadIdx.x] = thread_sum_sq;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            sum_shared[threadIdx.x] += sum_shared[threadIdx.x + stride];
            sum_sq_shared[threadIdx.x] += sum_sq_shared[threadIdx.x + stride];
        }
        __syncthreads();
    }

    float feature_sum = sum_shared[0];
    float feature_sum_sq = sum_sq_shared[0];
    float mean = feature_sum / batch_size;
    float variance = (feature_sum_sq - feature_sum * mean) / (batch_size - 1);

    if (is_training && threadIdx.x == 0) {
        running_mean[feature_idx] = (1 - momentum) * running_mean[feature_idx] + momentum * mean;
        running_var[feature_idx] = (1 - momentum) * running_var[feature_idx] + momentum * variance;
    }

    if (!is_training) {
        mean = running_mean[feature_idx];
        variance = running_var[feature_idx];
    }

    float inv_std = 1.0f / sqrt(variance + eps);
    float gamma = bn_weight[feature_idx];
    float beta = bn_bias[feature_idx];

    for (int i = threadIdx.x; i < batch_size; i += blockDim.x) {
        int idx = i * num_features + feature_idx;
        float val = input[idx] * s;
        output[idx] = (val - mean) * inv_std * gamma + beta;
    }
}

torch::Tensor fused_scale_bn_cuda(
    torch::Tensor input,
    torch::Tensor scale,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool is_training,
    float momentum,
    float eps) {

    auto num_features = input.size(1);
    auto batch_size = input.size(0);
    auto output = torch::empty_like(input);

    int block_size = 256;
    dim3 grid(num_features);
    size_t shared_mem = 2 * block_size * sizeof(float);

    fused_scale_bn_kernel<<<grid, block_size, shared_mem>>>(
        input.data_ptr<float>(),
        scale.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_features,
        eps,
        momentum,
        is_training);

    return output;
}
"""

fused_scale_bn_cpp = """
torch::Tensor fused_scale_bn_cuda(
    torch::Tensor input,
    torch::Tensor scale,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool is_training,
    float momentum,
    float eps);
"""

fused_scale_bn = load_inline(
    name='fused_scale_bn',
    cpp_sources=fused_scale_bn_cpp,
    cuda_sources=fused_scale_bn_source,
    functions=['fused_scale_bn_cuda'],
    verbose=True,
    extra_cuda_cflags=['-O2']
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scale_shape, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.scale = nn.Parameter(torch.randn(scale_shape))
        self.bn = nn.BatchNorm1d(out_features, eps=eps, momentum=momentum)
        self.bn.weight.data.fill_(1.0)
        self.bn.bias.data.fill_(0.0)

    def forward(self, x):
        x = self.gemm(x)
        x = fused_scale_bn.fused_scale_bn_cuda(
            x,
            self.scale,
            self.bn.weight,
            self.bn.bias,
            self.bn.running_mean,
            self.bn.running_var,
            self.training,
            self.bn.momentum,
            self.bn.eps
        )
        return x
